const phaseRender=render,phaseRole=renderRole;
render=function(){phaseRender();renderTradeDecisions();const icons=Economy.icons;$('stats').querySelectorAll('.stat').forEach((el,i)=>{if(Game.goods[i]==='equipment')el.querySelector('span').textContent='Made in workshops';if(Game.goods[i]==='materials')el.querySelector('span').textContent='Made from timber + stone';});$('stats').querySelectorAll('.stat small:first-child').forEach((el,i)=>{if(i<Game.goods.length)el.textContent=icons[Game.goods[i]]+' '+(Game.goods[i]==='money'?'Treasury':Game.goods[i]);});};
renderRole=function(){phaseRole();if(role!=='economy')return;const box=document.createElement('section');box.className='trade-panel';box.innerHTML=`<hr><h3>🔄 Trade with another country</h3><p class="role-intro">Offer a fair exchange. The other country must accept in Decide. An accepted agreement ships goods for 3 turns when both sides can pay.</p>${field('Trading partner','tradePartner',state.countries.filter(c=>c.id!==active).map(c=>[c.id,c.name]),state.countries.find(c=>c.id!==active)?.id)}${field('We give','tradeGive',Game.goods.map(k=>[k,Economy.icons[k]+' '+k]),'timber')}<label class="field">Amount we give<input id="tradeGiveQty" type="number" min="1" max="500" value="10"></label>${field('We receive','tradeTake',Game.goods.map(k=>[k,Economy.icons[k]+' '+k]),'iron')}<label class="field">Amount we receive<input id="tradeTakeQty" type="number" min="1" max="500" value="5"></label><button id="offerTrade">Propose exchange</button><h3>🏭 How goods become useful</h3><div class="recipe">🪵 2 timber + 🪨 1 stone → 🧱 1 material<br><small>Settlements and workshops make building materials.</small></div><div class="recipe">⛏ 2 iron + 🧱 1 material → ⚔ 1 equipment<br><small>Workshops make equipment for recruitment.</small></div><p class="role-intro">A storehouse adds 300 capacity to each stored good. Food loses 1% to spoilage each turn. Money has no storage limit.</p><h3>🚚 Trade in progress</h3><div id="tradeProgress"></div>`;$('rolePanel').append(box);if(state.phase!=='implement')box.querySelectorAll('input,select,button').forEach(e=>e.disabled=true);$('offerTrade').onclick=()=>action(()=>Economy.propose(state,active,Number($('tradePartner').value),$('tradeGive').value,Number($('tradeGiveQty').value),$('tradeTake').value,Number($('tradeTakeQty').value)),'Trade proposed. The receiving country answers during Decide.');$('tradeProgress').innerHTML=state.tradeDeals.filter(d=>d.from===active||d.to===active).map(d=>`<p>🤝 ${esc(state.countries[d.from].name)} ↔ ${esc(state.countries[d.to].name)}: ${d.remaining} shipping turns left.</p>`).join('')+state.shipments.filter(d=>d.from===active||d.to===active).map(d=>`<p>🚚 ${d.qty} ${esc(d.good)} → ${esc(state.countries[d.to].name)} · ${d.remaining} turns${Game.relation(state,d.from,d.to)==='enemy'?' · Held by war':''}</p>`).join('')||'<p class="role-intro">No active trades yet.</p>';};
function renderTradeDecisions(){if(state.phase!=='decide')return;for(const o of state.tradeOffers){const card=document.createElement('article');card.className='decision';card.innerHTML=`<h3>🔄 Proposed trade</h3><p>${esc(state.countries[o.from].name)} gives <b>${o.giveQty} ${esc(o.give)}</b> for <b>${o.takeQty} ${esc(o.take)}</b> from ${esc(state.countries[o.to].name)}.</p><p>Lasts 3 shipping turns. Travel takes time. If either country cannot pay, neither pays that turn.</p><button data-trade-accept="${o.id}">Receiving country: accept</button><button data-trade-decline="${o.id}">Decline</button>`;$('decisions').append(card);card.querySelector('[data-trade-accept]').onclick=()=>action(()=>Economy.accept(state,o.id,o.to,true),'Trade agreement accepted.');card.querySelector('[data-trade-decline]').onclick=()=>action(()=>Economy.accept(state,o.id,o.to,false),'Trade declined.');}}
render();
